-- 0002 — SQLite's triggers, ported to plpgsql (scheduler audit 10/10/26 RM-13).
-- Generated by pg_copy.trigger_statements from the current schema; the copy
-- (scripts/run_pg_copy.py) applies that function's output, which this file
-- records for review. The boot's own DROP/CREATE TRIGGER is a no-op on
-- Postgres (db_dialect.PgConnection).
CREATE OR REPLACE FUNCTION cavnar_outcomes_changed() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.changed_at := to_char(timezone('UTC', clock_timestamp()), 'YYYY-MM-DD HH24:MI:SS.MS'); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_outcomes_changed_ins ON recommendation_outcomes;
CREATE TRIGGER trg_outcomes_changed_ins BEFORE INSERT ON recommendation_outcomes FOR EACH ROW EXECUTE FUNCTION cavnar_outcomes_changed();
DROP TRIGGER IF EXISTS trg_outcomes_changed_upd ON recommendation_outcomes;
CREATE TRIGGER trg_outcomes_changed_upd BEFORE UPDATE ON recommendation_outcomes FOR EACH ROW WHEN (NEW.status IS DISTINCT FROM OLD.status OR NEW.verdict IS DISTINCT FROM OLD.verdict OR NEW.source_key IS DISTINCT FROM OLD.source_key OR NEW.metric IS DISTINCT FROM OLD.metric OR NEW.started_on IS DISTINCT FROM OLD.started_on OR NEW.evaluate_on IS DISTINCT FROM OLD.evaluate_on OR NEW.after_start IS DISTINCT FROM OLD.after_start OR NEW.after_end IS DISTINCT FROM OLD.after_end OR NEW.recheck_verdict IS DISTINCT FROM OLD.recheck_verdict OR NEW.owner_checkin IS DISTINCT FROM OLD.owner_checkin OR NEW.baseline_overlaps_trigger IS DISTINCT FROM OLD.baseline_overlaps_trigger OR NEW.concurrent IS DISTINCT FROM OLD.concurrent OR NEW.delta IS DISTINCT FROM OLD.delta OR NEW.delta_pct IS DISTINCT FROM OLD.delta_pct OR NEW.baseline_value IS DISTINCT FROM OLD.baseline_value OR NEW.noise_sigma IS DISTINCT FROM OLD.noise_sigma OR NEW.baseline_kind IS DISTINCT FROM OLD.baseline_kind) EXECUTE FUNCTION cavnar_outcomes_changed();
CREATE OR REPLACE FUNCTION cavnar_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'integrity_constraint_violation'; END $$;
DROP TRIGGER IF EXISTS intel_pattern_history_append_only ON intel_pattern_history;
CREATE TRIGGER intel_pattern_history_append_only BEFORE UPDATE ON intel_pattern_history FOR EACH ROW EXECUTE FUNCTION cavnar_append_only();
CREATE OR REPLACE FUNCTION cavnar_intel_features_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.version := 3; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_intel_features_version ON intel_features;
CREATE TRIGGER trg_intel_features_version BEFORE INSERT ON intel_features FOR EACH ROW WHEN (NEW.version IS NULL) EXECUTE FUNCTION cavnar_intel_features_version();
CREATE OR REPLACE FUNCTION cavnar_no_double_booking() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.copy = 'published' AND NEW.person_ref IS NOT NULL AND NEW.starts_at IS NOT NULL AND NEW.ends_at IS NOT NULL AND EXISTS (SELECT 1 FROM schedule_shifts o WHERE o.history_id = NEW.history_id AND o.copy = NEW.copy AND o.id IS DISTINCT FROM NEW.id AND o.person_ref = NEW.person_ref AND o.starts_at < NEW.ends_at AND NEW.starts_at < o.ends_at AND position(' ' || o.shift_id || ' ' in ' ' || COALESCE(NEW.overlap_ok_with, '') || ' ') = 0 AND position(' ' || NEW.shift_id || ' ' in ' ' || COALESCE(o.overlap_ok_with, '') || ' ') = 0) THEN RAISE EXCEPTION 'schedule_shifts: double booking' USING ERRCODE = 'integrity_constraint_violation'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS schedule_shifts_no_double_booking ON schedule_shifts;
CREATE TRIGGER schedule_shifts_no_double_booking BEFORE INSERT ON schedule_shifts FOR EACH ROW EXECUTE FUNCTION cavnar_no_double_booking();
